// Live fitting in the browser: the same Rust core as the CLI, compiled to wasm.
// Data slices are generated by scripts/make_docs_figures.py --bundle-slice, as real
// gzipped NIfTI-1 files; NiiVue reads and displays them directly (no reimplemented
// NIfTI parsing here).
//
// This module is the entry point and owns startup only: `main` reads as a
// sequence of stages, and each `wire*` function owns the listeners for one region
// of the page, so a control's wiring sits with the other controls it belongs
// with. Every behaviour those listeners reach for lives in the module that owns
// that region.
import { paintIcons } from "./vendor/icons.js";
import { wireCite, closeCite } from "./cite.js";
import { $, status } from "./dom.js";
import { app, editor, nvIn, nvOut } from "./state.js";
import { loadBundle, fetchOrThrow, loadWasm } from "./bundles.js";
import { setEditorText, showTab, syncYamlScroll } from "./recipe.js";
import { stripProtocolComments } from "./surface.js";
import {
  onFilesClick,
  onFrameChange,
  goToFrame,
  showInputsTab,
  syncFilesHighlight,
  syncFrameFill,
} from "./inputs.js";
import {
  applyViewerTheme,
  linkViewers,
  onColormapChange,
  populateColormaps,
  showMapView,
  showOutput,
  sizeViewers,
} from "./viewers.js";
import {
  closeDistributions,
  copyCsv,
  openDistributions,
  renderMeasurements,
  showMeasureView,
  toggleMeasureScope,
} from "./measure.js";
import { onDrawingStroke, wandOwnsWheel, wireDrawing } from "./draw.js";
import { wireSegment } from "./segment.js";
import { clearMapHover, onLocation, onMapHover, redrawCurve, resizeCurve } from "./curve.js";
import { closeFileModal, closeJsonModal, closeNotice, openMapModal } from "./modal.js";
import { onBrowse, onDrop } from "./drop.js";
import { THEMES, initTheme, onThemeChange, setFamily, setMode } from "./themes.js";
import { createLevelControl, repaintLevels } from "./level.js";
import { fitSlice } from "./fit.js";
import { loadModel } from "./model.js";

// ---------------------------------------------------------------------------
// Tooltips for the panel info buttons. One element, moved and refilled — a
// native `title` cannot be shown without the browser's ~1s delay, and these
// should appear the moment a reader asks.

let tipEl = null;

function showTip(anchor) {
  const text = anchor.dataset.tip;
  if (!text) return;
  if (!tipEl) {
    tipEl = document.createElement("div");
    tipEl.className = "tip";
    tipEl.setAttribute("role", "tooltip");
    document.body.append(tipEl);
  }
  tipEl.textContent = text;
  tipEl.hidden = false;
  // Measure after filling, then place: below the icon by default, flipped above
  // when there is no room, and clamped so it never runs off either edge.
  const a = anchor.getBoundingClientRect();
  const t = tipEl.getBoundingClientRect();
  const margin = 8;
  let left = a.left + a.width / 2 - t.width / 2;
  left = Math.max(margin, Math.min(left, window.innerWidth - t.width - margin));
  const below = a.bottom + 6;
  const top = below + t.height + margin > window.innerHeight ? a.top - t.height - 6 : below;
  tipEl.style.left = `${Math.round(left)}px`;
  tipEl.style.top = `${Math.round(top)}px`;
}

function hideTip() {
  if (tipEl) tipEl.hidden = true;
}

// Delegated, so info buttons added later need no wiring. Focus and blur are
// covered too, for readers who tab rather than hover.
function wireTips() {
  for (const [event, fn] of [
    ["pointerenter", (e) => showTip(e.target)],
    ["pointerleave", hideTip],
    ["focusin", (e) => showTip(e.target)],
    ["focusout", hideTip],
  ]) {
    document.addEventListener(
      event,
      (e) => {
        const info = e.target instanceof Element ? e.target.closest(".info") : null;
        if (!info) return;
        fn({ ...e, target: info });
      },
      true,
    );
  }
  // A tooltip must not outlive the thing it describes scrolling away.
  window.addEventListener("scroll", hideTip, true);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") hideTip();
  });
}

// The recipe fields collapse away on a narrow screen, where they would otherwise
// push the viewers off the first screenful. The header and model picker stay, so
// switching models needs no expanding first.
const NARROW = "(max-width: 900px)";

function setRecipeCollapsed(collapsed) {
  const card = document.querySelector(".recipe-card");
  card.classList.toggle("collapsed", collapsed);
  const btn = $("recipe-collapse");
  btn.textContent = collapsed ? "Show" : "Hide";
  btn.setAttribute("aria-expanded", String(!collapsed));
  // The chart and viewers are sized by the space this frees or takes.
  resizeCurve();
  sizeViewers();
}

function wireRecipeCollapse() {
  const narrow = window.matchMedia?.(NARROW);
  // Start collapsed on a narrow screen, expanded otherwise.
  setRecipeCollapsed(Boolean(narrow?.matches));
  $("recipe-collapse").onclick = () =>
    setRecipeCollapsed(!document.querySelector(".recipe-card").classList.contains("collapsed"));
  // Rotating a phone changes which default is right.
  narrow?.addEventListener?.("change", (e) => setRecipeCollapsed(e.matches));
}

// The two always-present viewers, and the state they share.
function setUpViewers() {
  // Otherwise the canvas backing store renders at 1x and is upscaled by CSS to
  // its layout size — soft/blurry on any HiDPI (retina) display, regardless of
  // how much native resolution the data has. NiiVue's own `resizeListener`
  // (called on every model load and viewer resize) keeps the backing store
  // matched to `devicePixelRatio` once this is set.
  nvIn.setHighResolutionCapable(true);
  nvOut.setHighResolutionCapable(true);
  applyViewerTheme();
  populateColormaps();

  // Synced crosshairs both ways, so dragging in either viewer moves the other —
  // established here empty, and re-established by `linkViewers` as the fitted map
  // comes and goes. Location handling is registered on both, so a click on the
  // fitted map updates the voxel curve exactly as one on the inputs viewer does.
  linkViewers();
  nvIn.onLocationChange = onLocation;
  nvOut.onLocationChange = onLocation;
  // NiiVue steps a volume's 4D frame on its own (ArrowLeft/ArrowRight, bound
  // internally to `frame_previous`/`frame_next`) whenever the inputs viewer has
  // focus — every path ends at `setFrame4D`, which fires this callback, so the
  // slider and label stay in sync with the arrow keys as they do with the wheel.
  nvIn.onFrameChange = (volume, frame) => {
    if (!app.current || volume.id !== app.current.volume.id) return;
    app.current.frame = frame;
    $("frame").value = String(frame);
    $("frame-label").textContent = app.current.meta.labels[frame] ?? "";
    syncFrameFill();
    syncFilesHighlight();
  };
}

// The theme picker: a family, plus a light/dark toggle that follows the docs
// page until the reader overrides it.
//
// The three repaints live here rather than in `themes.js`: which canvases,
// charts and controls exist is this page's business, not the theme registry's.
// Each seam already existed for its own reasons; a theme change is the only
// caller that needs all three at once.
function wireTheme() {
  onThemeChange(() => {
    applyViewerTheme();
    repaintLevels();
    redrawCurve();
  });
  const select = $("theme-family");
  for (const { id, label } of THEMES) {
    const opt = document.createElement("option");
    opt.value = id;
    opt.textContent = label;
    select.append(opt);
  }
  // Reflect the applied theme rather than tracking it separately: the first
  // apply happens in `initTheme`, after this function runs, and the parent
  // page's own toggle can change it later with no click here.
  onThemeChange(() => {
    select.value = document.documentElement.dataset.theme;
    // Two marks, one per mode. Swapped here rather than by a `<picture>` media
    // query: the mode is this app's own attribute, and a reader on a light OS can
    // be looking at a dark theme — a media query would pick the wrong one.
    $("panel-logo").src =
      document.documentElement.dataset.mode === "light" ? "./logo_light.png" : "./logo_dark.png";
    $("theme-pick").title = `Theme: ${THEMES.find((t) => t.id === select.value)?.label ?? ""}`;
    // A two-state control, not two switches: each half selects its own mode, so
    // clicking the one already lit does nothing.
    const dark = document.documentElement.dataset.mode === "dark";
    for (const [id, on] of [["mode-dark", dark], ["mode-light", !dark]]) {
      $(id).classList.toggle("active", on);
      $(id).setAttribute("aria-pressed", String(on));
    }
  });
  select.onchange = (e) => setFamily(e.target.value);
  $("mode-light").onclick = () => setMode("light");
  $("mode-dark").onclick = () => setMode("dark");
}

// The model picker, the recipe editor, and Fit.
function wireRecipeControls() {
  $("model").onchange = (e) => loadModel(e.target.value);
  $("fit").onclick = fitSlice;
  const toggleRecipeView = () =>
    showTab($("tab-form").classList.contains("active") ? "yaml" : "form");
  $("tab-form").onclick = toggleRecipeView;
  $("tab-yaml").onclick = toggleRecipeView;
  // The textarea's own text may carry a generated protocol-comment block
  // (see `withProtocolComments`); it must never reach the recipe parser.
  $("cfg-yaml").oninput = (e) => setEditorText(stripProtocolComments(e.target.value));
  $("cfg-yaml").addEventListener("scroll", syncYamlScroll);
}

// Accumulated wheel `deltaY` crosses this before a frame steps — tuned to the
// ~100-120 one wheel notch reports, and large enough that one full trackpad
// swipe is one frame rather than several.
const WHEEL_STEP_THRESHOLD = 100;

// The inputs viewer: its tabs, the frame slider, and wheel-to-scrub.
function wireInputsControls() {
  const toggleInputsView = () =>
    showInputsTab($("tab-viewer").classList.contains("active") ? "files" : "viewer");
  $("tab-viewer").onclick = toggleInputsView;
  $("tab-files").onclick = toggleInputsView;
  $("frame").oninput = onFrameChange;
  $("files-tree").addEventListener("click", onFilesClick);

  // Wheel-to-scrub, alongside the slider: a reader hovering the inputs viewer
  // steps through frames without reaching for it. Captured (not bubble-phase)
  // and stopped here, ahead of NiiVue's own wheel-to-zoom handler on the canvas
  // — this viewer's wheel gesture means "step frames", not "zoom the slice".
  //
  // A single mouse-wheel notch and a single trackpad swipe both arrive as a
  // *stream* of wheel events, so stepping on every event blows through several
  // frames per gesture. Accumulate `deltaY` and step only once it crosses the
  // threshold.
  $("viewer-in").addEventListener(
    "wheel",
    (e) => {
      if (!app.current) return;
      // The wand regrows its region on the wheel, and it is the more specific
      // gesture: while it is armed the event is left alone so NiiVue receives it
      // here too, rather than only on the fitted map.
      if (wandOwnsWheel()) return;
      const [, , , nt] = app.current.meta.dims;
      if (nt <= 1) return;
      e.preventDefault();
      e.stopPropagation();
      app.wheelAccum += e.deltaY;
      if (Math.abs(app.wheelAccum) < WHEEL_STEP_THRESHOLD) return;
      const dir = app.wheelAccum > 0 ? 1 : -1;
      app.wheelAccum = 0;
      const id = app.current.volume.id;
      const t = Math.min(nt - 1, Math.max(0, nvIn.getFrame4D(id) + dir));
      if (t === nvIn.getFrame4D(id)) return;
      goToFrame(t);
    },
    { passive: false, capture: true },
  );
}

// The voxel-fit card's two views: one curve, one table of the drawn regions.
function wireMeasurements() {
  const toggle = () =>
    showMeasureView($("tab-curve").classList.contains("active") ? "measurements" : "curve");
  $("tab-curve").onclick = toggle;
  $("tab-measure").onclick = toggle;
  $("measure-scope").onclick = toggleMeasureScope;
  $("measure-csv").onclick = copyCsv;
  $("measure-chart").onclick = openDistributions;
  $("chart-modal-close").onclick = closeDistributions;
}

// The fitted map: output and colormap pickers, slice/multiplanar, window/level, ROI.
function wireMapControls() {
  $("output").onchange = (e) => {
    showOutput(e.target.value);
    // The table reports the map on screen, so it follows the picker.
    renderMeasurements();
  };
  $("colormap").onchange = onColormapChange;
  const toggleMapView = () =>
    showMapView($("tab-slice").classList.contains("active") ? "planes" : "slice");
  $("tab-slice").onclick = toggleMapView;
  $("tab-planes").onclick = toggleMapView;
  $("open-map-modal").onclick = openMapModal;
  wireDrawing();
  wireSegment();
  app.levelMain = createLevelControl("mlevel");
  // Recompute after each stroke, so the numbers track the region as it is drawn.
  // Any viewer can be drawn on — including the modal's, which comes and goes.
  // `draw.js` mirrors the stroke between them; this says what to do afterwards.
  onDrawingStroke(renderMeasurements);
  nvOut.canvas.addEventListener("mousemove", onMapHover);
  nvOut.canvas.addEventListener("mouseleave", clearMapHover);
}

// Dropping or browsing to a reader's own dataset.
function wireDataDrop() {
  // `dragover` must be prevented for a drop to fire at all; `dragleave` is
  // filtered to the panel itself, since it also fires when the cursor crosses
  // onto a child.
  const dropZone = $("drop-wrap");
  dropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    dropZone.classList.add("drop-over");
  });
  dropZone.addEventListener("dragleave", (e) => {
    if (e.target === dropZone) dropZone.classList.remove("drop-over");
  });
  dropZone.addEventListener("drop", onDrop);
  $("browse-folder").onclick = () => $("folder-input").click();
  $("folder-input").addEventListener("change", (e) => {
    if (e.target.files.length) onBrowse(e.target.files);
    // Reset, so picking the same folder twice fires `change` again.
    e.target.value = "";
  });
}

// Every dialog, and the one key that closes any of them.
function wireModals() {
  $("file-modal-close").onclick = closeFileModal;
  $("json-modal-close").onclick = closeJsonModal;
  $("notice-close").onclick = closeNotice;
  wireCite();
  for (const [id, close] of [
    ["file-modal", closeFileModal],
    ["json-modal", closeJsonModal],
    ["notice-modal", closeNotice],
    ["cite-modal", closeCite],
    ["chart-modal", closeDistributions],
  ]) {
    // The backdrop closes; the card inside it does not.
    $(id).addEventListener("click", (e) => {
      if (e.target === $(id)) close();
    });
  }
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (!$("file-modal").hidden) closeFileModal();
    if (!$("json-modal").hidden) closeJsonModal();
    if (!$("notice-modal").hidden) closeNotice();
    if (!$("cite-modal").hidden) closeCite();
    if (!$("chart-modal").hidden) closeDistributions();
  });
}

// Fill the model picker from the payload index. False means there is nothing to
// show, which is a hard stop rather than an empty page.
async function populateModels() {
  let index;
  try {
    index = await (await fetchOrThrow("./data/index.json")).json();
  } catch (e) {
    status(`Could not load the model index: ${e.message}`, "error");
    return false;
  }
  app.modelNames = index.models;
  const select = $("model");
  for (const name of index.models) {
    let meta;
    try {
      meta = await loadBundle(name);
    } catch (e) {
      // One unreadable payload should not cost the reader every other model.
      status(`Could not load ${name}: ${e.message}`, "error");
      continue;
    }
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = meta.title;
    select.append(opt);
  }
  return select.options.length > 0;
}

async function main() {
  // Icons before anything measures a control: an unfilled placeholder has no
  // width, so a layout read taken before this would be wrong.
  paintIcons();
  // Theme first: `wireTheme` registers the repaint callback, and `initTheme`
  // sets the attributes — both before `attachTo`, so the canvases are created
  // against the right background rather than flashing another theme's.
  wireTheme();
  initTheme();
  await nvIn.attachTo("gl-in");
  await nvOut.attachTo("gl-out");
  setUpViewers();
  wireTips();
  wireRecipeCollapse();
  wireRecipeControls();
  wireInputsControls();
  wireMapControls();
  wireDataDrop();
  wireMeasurements();
  wireModals();

  app.wasm = await loadWasm();
  if (await populateModels()) await loadModel($("model").value);
}

main();

// Read-only state accessor for automated smoke-testing; no UI depends on this.
window.__playground = { maps: () => app.lastMaps, editor: () => editor };
